To segregate even and odd elements in a linked list, we can create two separate lists for even and odd elements. Here is a Python code to do this:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def segregate_even_odd(head):
    if not head or not head.next:
        return head

    even_head = even_tail = odd_head = odd_tail = None

    curr = head

    while curr:
        next_node = curr.next
        curr.next = None

        if curr.data % 2 == 0:
            if even_tail:
                even_tail.next = curr
                even_tail = curr
            else:
                even_head = even_tail = curr
        else:
            if odd_tail:
                odd_tail.next = curr
                odd_tail = curr
            else:
                odd_head = odd_tail = curr

        curr = next_node

    even_tail.next = odd_head

    return even_head

def print_list(head):
    while head:
        print(head.data, end=" ")
        head = head.next
    print()

